    realtype x1 = 1.0/PARAM(P_rho_collagen);
    realtype x2 = SPVAR(SP_V_T_collagen)*x1;
    realtype x3 = 1.0/PARAM(P_Ve_T);
    realtype x4 = SPVAR(SP_V_T_apCAF)*PARAM(P_vol_apCAFcell);
    realtype x5 = SPVAR(SP_V_T_iCAF)*PARAM(P_vol_iCAFcell);
    realtype x6 = SPVAR(SP_V_T_myCAF)*PARAM(P_vol_myCAFcell);
    realtype x7 = SPVAR(SP_V_T_qPSC)*PARAM(P_vol_qPSCcell);
    realtype x8 = SPVAR(SP_V_T_C1) + SPVAR(SP_V_T_C2);
    realtype x9 = PARAM(P_V_Tmin) + x2 + x3*(PARAM(P_vol_Mcell)*(SPVAR(SP_V_T_Mac_M1) + SPVAR(SP_V_T_Mac_M2)) + PARAM(P_vol_Tcell)*(SPVAR(SP_V_T_CD8) + SPVAR(SP_V_T_CD8_exh) + SPVAR(SP_V_T_Tfh) + SPVAR(SP_V_T_Th) + SPVAR(SP_V_T_Th_exh) + SPVAR(SP_V_T_Treg)) + PARAM(P_vol_cell)*(SPVAR(SP_V_T_C_x) + x8) + x4 + x5 + x6 + x7);
    realtype x10 = 1.0/x9;
    realtype x11 = SPVAR(SP_V_T_CCL5)*x10;
    realtype x12 = PARAM(P_CCL5_50_Treg) + x11;
    realtype x13 = PARAM(P_k_CCR5_Treg_rec)/x12;
    realtype x14 = PARAM(P_q_Treg_T_in)*x9;
    realtype x15 = std::pow(x8, 2.0);
    realtype x16 = PARAM(P_K_C2_recruit) + x15;
    realtype x17 = 1.0/x16;
    realtype x18 = x15*x17;
    realtype x19 = x14*x18;
    realtype x20 = SPVAR(SP_V_T_CCL5)*x13 + x19;
    realtype x21 = SPVAR(SP_V_T_CXCL12)*x10;
    realtype x22 = PARAM(P_CXCL12_50_Texcl) + x21;
    realtype x23 = 1.0/x22;
    realtype x24 = -x21*x23 + 1.0;
    realtype x25 = x18*x24;
    realtype x26 = PARAM(P_q_CD8_T_in)*x9;
    realtype x27 = x25*x26;
    realtype x28 = 1.0/PARAM(P_V_C);
    realtype x29 = x28/PARAM(P_gamma_C_aPD1);
    realtype x30 = PARAM(P_q_LN_aPD1)*x29;
    realtype x31 = PARAM(P_q_P_aPD1)*x29;
